n// ============ DELIVERY SLOT ============\n\nmodel DeliverySlot {\n  id         String  @id @default(cuid())\n  name       String\n  startTime  String\n  endTime    String\n  cutoffTime String?\n  isActive   Boolean @default(true)\n}\n\n// ============ NOTIFICATION LOG ============\n\nmodel NotificationLog {\n  id          String   @id @default(cuid())\n  userId      String\n  channel     String   @default(\"PUSH\")\n  templateKey String?\n  title       String?\n  body        String?\n  status      String   @default(\"SENT\")\n  createdAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"notification_log\")\n}\n\n// ============ SUPPORT TICKET ============\n\nmodel SupportTicket {\n  id          String         @id @default(cuid())\n  userId      String\n  orderId     String?\n  subject     String\n  description String\n  status      TicketStatus   @default(OPEN)\n  priority    TicketPriority @default(MEDIUM)\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n\n  messages TicketMessage[]\n  user     User            @relation(fields: [userId], references: [id])\n  order    Order?          @relation(fields: [orderId], references: [id])\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_ticket\")\n}\n\nenum TicketStatus {\n  OPEN\n  INPROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum TicketPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nmodel TicketMessage {\n  id        String   @id @default(cuid())\n  ticketId  String\n  senderId  String?\n  message   String\n  mediaUrls String[]\n  createdAt DateTime @default(now())\n\n  ticket SupportTicket @relation(fields: [ticketId], references: [id])\n\n  @@index([ticketId])\n  @@map(\"ticket_message\")\n}\n\n// ============ REFERRAL ============\n\nmodel Referral {\n  id           String   @id @default(cuid())\n  referrerId   String\n  referredId   String?\n  referralCode String   @unique\n  status       String   @default(\"PENDING\")\n  rewardAmount Decimal  @default(0)\n  rewardPaid   Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  referrer User  @relation(\"referrer\", fields: [referrerId], references: [id])\n  referred User? @relation(\"referred\", fields: [referredId], references: [id])\n\n  @@index([referrerId])\n  @@index([referralCode])\n  @@map(\"referral\")\n}\n\n// ============ LOYALTY POINTS ============\n\nmodel LoyaltyPoints {\n  id             String   @id @default(cuid())\n  userId         String   @unique\n  points         Int      @default(0)\n  lifetimePoints Int      @default(0)\n  tier           String   @default(\"BRONZE\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@map(\"loyalty_points\")\n}\n\nmodel LoyaltyTransaction {\n  id          String   @id @default(cuid())\n  userId      String\n  points      Int\n  type        String\n  reference   String?\n  description String?\n  createdAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@map(\"loyalty_transaction\")\n}\n\n// ============ COUPONS & PROMOTIONS ============\n\nmodel Coupon {\n  id                String       @id @default(cuid())\n  code              String       @unique\n  description       String?\n  discountType      DiscountType\n  discountValue     Decimal\n  maxDiscount       Decimal?\n  minOrderValue     Decimal?\n  scope             CouponScope  @default(PLATFORM)\n  kitchenPartnerId  String?\n  validFrom         DateTime\n  validTo           DateTime\n  usageLimitTotal   Int?\n  usageLimitPerUser Int?         @default(1)\n  isActive          Boolean      @default(true)\n  createdAt         DateTime     @default(now())\n\n  redemptions    CouponRedemption[]\n  kitchenPartner KitchenPartner?    @relation(fields: [kitchenPartnerId], references: [id])\n\n  @@index([code])\n  @@index([kitchenPartnerId])\n}\n\nenum DiscountType {\n  FLAT\n  PERCENTAGE\n}\n\nenum CouponScope {\n  PLATFORM\n  KITCHEN_SPECIFIC\n}\n\nmodel CouponRedemption {\n  id             String   @id @default(cuid())\n  couponId       String\n  userId         String\n  orderId        String   @unique\n  discountAmount Decimal\n  createdAt      DateTime @default(now())\n\n  coupon Coupon @relation(fields: [couponId], references: [id])\n  order  Order  @relation(fields: [orderId], references: [id])\n\n  @@index([couponId])\n  @@index([userId])\n}\n\n// ============ PAYMENT OFFERS ============\n\nenum PaymentOfferType {\n  UPI\n  WALLET\n  CARDS\n  NETBANKING\n  ALL\n}\n\nmodel PaymentOffer {\n  id            String           @id @default(cuid())\n  name          String\n  description   String?\n  offerType     PaymentOfferType\n  discountType  DiscountType\n  discountValue Decimal\n  maxDiscount   Decimal?\n  minOrderValue Decimal?\n  validFrom     DateTime\n  validTo       DateTime\n  isActive      Boolean          @default(true)\n  createdAt     DateTime         @default(now())\n}\n\n// ============ REFUNDS ============\n\nmodel Refund {\n  id               String       @id @default(cuid())\n  orderId          String\n  orderItemId      String?\n  paymentId        String\n  razorpayRefundId String?      @unique\n  amount           Decimal\n  reason           RefundReason\n  status           RefundStatus @default(INITIATED)\n  initiatedAt      DateTime     @default(now())\n  processedAt      DateTime?\n\n  order   Order   @relation(fields: [orderId], references: [id])\n  payment Payment @relation(fields: [paymentId], references: [id])\n\n  @@index([orderId])\n  @@index([status])\n}\n\nenum RefundReason {\n  ITEM_OUT_OF_STOCK\n  KITCHEN_REJECTED\n  CUSTOMER_CANCELLED\n  QUALITY_ISSUE\n  LATE_DELIVERY\n  OTHER\n}\n\nenum RefundStatus {\n  INITIATED\n  PROCESSING\n  PROCESSED\n  FAILED\n}\n\n// ============ PAYOUTS ============\n\nmodel KitchenPayout {\n  id                   String       @id @default(cuid())\n  kitchenPartnerId     String\n  orderId              String       @unique\n  grossAmount          Decimal\n  commissionAmount     Decimal\n  couponBorneByKitchen Decimal      @default(0)\n  netAmount            Decimal\n  status               PayoutStatus @default(PENDING)\n  razorpayPayoutId     String?      @unique\n  settledAt            DateTime?\n  createdAt            DateTime     @default(now())\n\n  kitchenPartner KitchenPartner @relation(fields: [kitchenPartnerId], references: [id])\n  order          Order          @relation(fields: [orderId], references: [id])\n\n  @@index([kitchenPartnerId, status])\n}\n\nmodel DeliveryPartnerPayout {\n  id                String       @id @default(cuid())\n  deliveryPartnerId String\n  orderId           String       @unique\n  amount            Decimal\n  status            PayoutStatus @default(PENDING)\n  razorpayPayoutId  String?      @unique\n  settledAt         DateTime?\n  createdAt         DateTime     @default(now())\n\n  deliveryPartner DeliveryPartner @relation(fields: [deliveryPartnerId], references: [id])\n  order           Order           @relation(fields: [orderId], references: [id])\n\n  @@index([deliveryPartnerId, status])\n}\n\nenum PayoutStatus {\n  PENDING\n  PROCESSING\n  SETTLED\n  FAILED\n}\n\n// ============ KITCHEN ADDRESS & ZONE ============\n\nmodel KitchenAddress {\n  id               String         @id @default(cuid())\n  kitchenPartnerId String         @unique\n  lineOne          String\n  pincode          String\n  latitude         Float\n  longitude        Float\n  kitchenPartner   KitchenPartner @relation(fields: [kitchenPartnerId], references: [id])\n}\n\n// ============ DAILY BATCH STOCK ============\n\nmodel MenuItemDailyStock {\n  id               String   @id @default(cuid())\n  menuItemId       String\n  serviceDate      DateTime\n  totalQuantity    Int\n  reservedQuantity Int      @default(0)\n  soldQuantity     Int      @default(0)\n  menuItem         MenuItem @relation(fields: [menuItemId], references: [id])\n\n  @@unique([menuItemId, serviceDate])\n  @@index([menuItemId, serviceDate])\n}\n\n// ============ ADMIN PROTECTION ============\n\nenum AdminPermission {\n  MANAGE_ADMINS\n  APPROVE_KYC\n  MANAGE_CATALOG\n  ISSUE_REFUNDS\n  MANAGE_PAYOUTS\n  MANAGE_COUPONS\n  VIEW_FINANCIALS\n  MANAGE_SUPPORT\n  BAN_USERS\n  MANAGE_CMS\n}\n\nmodel AdminProfile {\n  id              String            @id @default(cuid())\n  userId          String            @unique\n  permissions     AdminPermission[]\n  isActive        Boolean           @default(true)\n  invitedByUserId String?\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@map(\"admin_profile\")\n}\n\nmodel AdminInvite {\n  id               String            @id @default(cuid())\n  token            String            @unique\n  permissions      AdminPermission[]\n  createdByUserId  String\n  expiresAt        DateTime\n  consumedAt       DateTime?\n  consumedByUserId String?\n  revokedAt        DateTime?\n  createdAt        DateTime          @default(now())\n\n  @@index([token])\n  @@map(\"admin_invite\")\n}\n\nmodel AdminApprovalRequest {\n  id                String              @id @default(cuid())\n  actionType        AdminActionType\n  targetId          String?\n  payload           Json?\n  requestedByUserId String\n  status            AdminApprovalStatus @default(PENDING)\n  decidedByUserId   String?\n  decidedAt         DateTime?\n  createdAt         DateTime            @default(now())\n\n  @@index([status])\n  @@index([actionType])\n  @@map(\"admin_approval_request\")\n}\n\nenum AdminActionType {\n  REMOVE_ADMIN\n  GRANT_PERMISSION\n  LARGE_REFUND\n  PAYOUT_SETTLEMENT\n  BAN_USER\n}\n\nenum AdminApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nmodel AdminAuditLog {\n  id          String   @id @default(cuid())\n  actorUserId String\n  action      String\n  targetType  String?\n  targetId    String?\n  metadata    Json?\n  ipAddress   String?\n  createdAt   DateTime @default(now())\n\n  @@index([actorUserId])\n  @@index([targetType, targetId])\n  @@index([createdAt])\n  @@map(\"admin_audit_log\")\n}\n\nmodel TwoFactor {\n  id                      String    @id @default(cuid())\n  userId                  String\n  secret                  String\n  backupCodes             String\n  verified                Boolean   @default(false)\n  failedVerificationCount Int       @default(0)\n  lockedUntil             DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"two_factor\")\n}\n\nmodel UserCodEligibility {\n  id                      String   @id @default(cuid())\n  userId                  String   @unique\n  successfulPrepaidOrders Int      @default(0)\n  codRefusalCount         Int      @default(0)\n  isCodBlocked            Boolean  @default(false)\n  maxCodOrderValue        Decimal  @default(1000)\n  updatedAt               DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id])\n}\n\nenum RemittanceMethod {\n  UPI_TO_PLATFORM\n  BANK_TRANSFER\n  ADMIN_COLLECTED_CASH\n}\n\nenum RemittanceStatus {\n  PENDING\n  CONFIRMED\n  DISPUTED\n}\n\nmodel CashRemittance {\n  id                String           @id @default(cuid())\n  deliveryPartnerId String\n  amount            Decimal\n  method            RemittanceMethod\n  referenceId       String?\n  status            RemittanceStatus @default(PENDING)\n  confirmedByUserId String?\n  createdAt         DateTime         @default(now())\n  confirmedAt       DateTime?\n\n  deliveryPartner DeliveryPartner @relation(fields: [deliveryPartnerId], references: [id])\n\n  @@index([deliveryPartnerId, status])\n}\n\n// Swiggy's own documented concept — when a rider enters less than what was\n// actually collected (whether by honest error or deliberate under-reporting)\nmodel CodVariance {\n  id                String    @id @default(cuid())\n  orderId           String    @unique\n  deliveryPartnerId String\n  expectedAmount    Decimal\n  enteredAmount     Decimal\n  varianceAmount    Decimal // expected - entered\n  resolvedAt        DateTime?\n  resolutionNote    String?\n  createdAt         DateTime  @default(now())\n\n  order           Order           @relation(fields: [orderId], references: [id])\n  deliveryPartner DeliveryPartner @relation(fields: [deliveryPartnerId], references: [id])\n\n  @@index([deliveryPartnerId])\n  @@index([resolvedAt])\n}\n\n// ============ WISHLIST / FAVOURITES ============\n\nmodel WishlistItem {\n  id         String   @id @default(cuid())\n  userId     String\n  menuItemId String\n  createdAt  DateTime @default(now())\n\n  user     User     @relation(fields: [userId], references: [id])\n  menuItem MenuItem @relation(fields: [menuItemId], references: [id])\n\n  @@unique([userId, menuItemId])\n  @@index([userId])\n  @@map(\"wishlist_item\")\n}\n",
